  pf_om_pkg_ready: {
    IT: 'Pacchetto "{x}" pronto: {n} luoghi ({y}).\n\nOffline l\'app userà la vista radar e la voce di sistema: download istantaneo e zero ingombro. L\'audioguida parte da sola quando ti avvicini a un luogo, anche a schermo spento.',
    EN: 'Package "{x}" ready: {n} places ({y}).\n\nOffline the app will use the radar view and the system voice: instant download and zero footprint. The audio guide starts on its own when you approach a place, even with the screen off.',
    FR: "Pack « {x} » prêt : {n} lieux ({y}).\n\nHors ligne, l'app utilisera la vue radar et la voix système : téléchargement instantané et zéro encombrement. L'audioguide démarre tout seul quand vous approchez d'un lieu, même écran éteint.",
    ES: 'Paquete "{x}" listo: {n} lugares ({y}).\n\nSin conexión, la app usará la vista radar y la voz del sistema: descarga instantánea y cero ocupación. La audioguía arranca sola cuando te acercas a un lugar, incluso con la pantalla apagada.',
    DE: 'Paket „{x}" bereit: {n} Orte ({y}).\n\nOffline nutzt die App die Radaransicht und die Systemstimme: sofortiger Download und null Platzbedarf. Der Audioguide startet von selbst, wenn du dich einem Ort näherst, auch bei ausgeschaltetem Display.',
    RU: 'Пакет «{x}» готов: {n} мест ({y}).\n\nОфлайн приложение использует вид радара и системный голос: мгновенная загрузка и ноль места. Аудиогид запускается сам, когда вы приближаетесь к месту, даже при выключенном экране.',
    ZH: '离线包"{x}"已就绪：{n}个地点（{y}）。\n\n离线时应用将使用雷达视图和系统语音：瞬间下载、零占用。当你靠近某个地点时语音导览会自动开始，即使屏幕关闭。',
  },
  pf_om_pkg_error: { IT: 'Errore durante il download del pacchetto', EN: 'Error downloading the package', FR: 'Erreur lors du téléchargement du pack', ES: 'Error al descargar el paquete', DE: 'Fehler beim Herunterladen des Pakets', RU: 'Ошибка при загрузке пакета', ZH: '下载离线包时出错' },
  pf_om_sync_ok: { IT: 'Aggiornato: {n} luoghi nel pacchetto.', EN: 'Updated: {n} places in the package.', FR: 'Mis à jour : {n} lieux dans le pack.', ES: 'Actualizado: {n} lugares en el paquete.', DE: 'Aktualisiert: {n} Orte im Paket.', RU: 'Обновлено: в пакете {n} мест.', ZH: '已更新：离线包中有{n}个地点。' },
